package com.hospital.smartqueue.support; import com.hospital.smartqueue.common.domain.DomainException; import com.hospital.smartqueue.doctor.scheduling.application.*; import java.util.*;
/** Test-only identity; never component-scanned from production sources. */ public final class TrustedTestSchedulingAccessContext implements SchedulingAccessContext { private final StaffSchedulingIdentity identity; public TrustedTestSchedulingAccessContext(StaffSchedulingIdentity i){identity=i;} public StaffSchedulingIdentity current(){return identity;} public void requireRead(UUID h,UUID b,UUID d){allow(h,b,d,false);} public void requireManage(UUID h,UUID b,UUID d){allow(h,b,d,true);} private void allow(UUID h,UUID b,UUID d,boolean manage){if(!identity.hospitalIds().contains(h)||!identity.branchIds().contains(b)||!identity.doctorIds().contains(d)||(manage&&identity.role()!=SchedulingRole.SCHEDULING_MANAGER))throw new DomainException("FORBIDDEN","Scheduling access is not authorized");}}
